1	//! C6 legacy control step: the remaining legacy `k.machine.*` rows factorial
2	//! and fold fire, as one per-rule relation over the full C6 carriers:
3	//! `return.unary`, `return.if.true`, `return.if.false`, `return.match`,
4	//! `return.arguments.final` (frame pops), `primitive.value`, `cases.try`,
5	//! `cases.miss` and `cases.hit` (control rewrites).
6	//!
7	//! Each circuit fixes its rule at build time, selects it with the composed
8	//! dispatch owner and writes the post control, control origin, env root,
9	//! frame stack and helper result exactly as `fragments/legacy.proposed.rs`
10	//! plans them. A pop decrements the depth and zeroes the popped slot.
11	//! `cases.try` reads the first arm's body from canonical PROG. Charge is
12	//! LegacyComplete (work 1, reference cursor 1). Every unnamed lane is
13	//! preserved; canonicality is composed; enable = 0 is identity.
14	use midnight_zkir_v3::Instruction;
15	use midnight_zkir_v3::ir::Operand;
16	use mori_core::sherlock::helper_machine::c6_phys::{
17	    CONTROL_LANES, L_CONTROL, L_CONTROL_ORIGIN, L_ENV_ROOT, L_FRAME_COUNT,
18	};
19	use mori_core::sherlock::helper_machine::c6_phys_helper::{L_RESULT_RECORD, RESULT_LANES};
20	use mori_core::sherlock::helper_machine::shared::RuleIdC;
21	use thiserror::Error;
22	
23	use super::c6_program_context_canonical::C6ProgramContextArmCaptureInputs;
24	use super::c6_step_kit::{
25	    C6StepInputs, Composed, Em, charge_legacy, check_shapes, compose_canonical, disabled_identity,
26	    legacy_control_lanes, pop_frame, prefix, preserve_image, select, set_control,
27	    validate_pre_image,
28	};
29	
30	#[derive(Debug, Error)]
31	pub enum C6LegacyControlError {
32	    #[error("rule {0:?} is not a legacy control rule of this fragment")]
33	    Unsupported(RuleIdC),
34	    #[error("invalid scope")]
35	    InvalidScope,
36	    #[error("C6 legacy control emission: {0}")]
37	    Emit(String),
38	}
39	
40	pub const LEGACY_CONTROL_RULES: [RuleIdC; 9] = [
41	    RuleIdC::KMachineReturnUnary,
42	    RuleIdC::KMachineReturnIfTrue,
43	    RuleIdC::KMachineReturnIfFalse,
44	    RuleIdC::KMachineReturnMatch,
45	    RuleIdC::KMachineReturnArgumentsFinal,
46	    RuleIdC::KMachinePrimitiveValue,
47	    RuleIdC::KMachineCasesTry,
48	    RuleIdC::KMachineCasesMiss,
49	    RuleIdC::KMachineCasesHit,
50	];
51	
52	pub fn legacy_control_supported(rule: RuleIdC) -> bool {
53	    LEGACY_CONTROL_RULES.contains(&rule)
54	}
55	
56	// Result tags (c6_phys_helper::encode_result_record).
57	const R_APPEND_DONE: u128 = 9;
58	const R_SCALAR_VALUE: u128 = 10;
59	const R_SCALAR_ERROR: u128 = 11;
60	const R_EQUAL_DONE: u128 = 14;
61	const R_MATCH_MATCHED: u128 = 15;
62	const R_MATCH_NO_MATCH: u128 = 16;
63	
64	#[derive(Clone, Debug)]
65	pub struct C6LegacyControlBlock {
66	    pub instructions: Vec<Instruction>,
67	}
68	
69	pub struct C6LegacyControlEmitter {
70	    scope: String,
71	    next_temp: usize,
72	    composed: Composed,
73	}
74	
75	/// Register writes besides control: (origin, env root) when the rule sets them.
76	struct Regs {
77	    origin: Option<Operand>,
78	    env: Option<(Operand, Operand)>,
79	    pop: bool,
80	    clears_result: bool,
81	}
82	
83	impl C6LegacyControlEmitter {
84	    pub fn new(scope: &str) -> Result<Self, C6LegacyControlError> {
85	        if scope.trim().is_empty() || scope.contains('%') || scope.contains(".c6kit.") {
86	            return Err(C6LegacyControlError::InvalidScope);
87	        }
88	        Ok(Self {
89	            scope: scope.to_string(),
90	            next_temp: 0,
91	            composed: Composed::new(scope).map_err(C6LegacyControlError::Emit)?,
92	        })
93	    }
94	
95	    pub fn emit(
96	        &mut self,
97	        rule: RuleIdC,
98	        inputs: &C6StepInputs,
99	    ) -> Result<C6LegacyControlBlock, C6LegacyControlError> {
100	        if !legacy_control_supported(rule) {
101	            return Err(C6LegacyControlError::Unsupported(rule));
102	        }
103	        check_shapes(inputs).map_err(C6LegacyControlError::Emit)?;
104	        let scope = self.scope.clone();
105	        let mut em = Em {
106	            scope: &scope,
107	            next: self.next_temp,
108	            ins: Vec::new(),
109	        };
110	        let r = self.body(&mut em, rule, inputs);
111	        self.next_temp = em.next;
112	        r.map_err(C6LegacyControlError::Emit)?;
113	        Ok(C6LegacyControlBlock {
114	            instructions: em.ins,
115	        })
116	    }
117	
118	    fn body(&mut self, em: &mut Em, rule: RuleIdC, inputs: &C6StepInputs) -> Result<(), String> {
119	        let en = inputs.enable.clone();
120	        prefix(em, inputs);
121	        let top = validate_pre_image(em, inputs);
122	        select(&mut self.composed, em, rule, inputs)?;
123	
124	        let pre_i = &inputs.pre_image;
125	        let post_i = &inputs.post_image;
126	        let k: Vec<Operand> = pre_i[L_CONTROL..L_CONTROL + CONTROL_LANES].to_vec();
127	        let res: Vec<Operand> =
128	            inputs.pre_helper[L_RESULT_RECORD..L_RESULT_RECORD + RESULT_LANES].to_vec();
129	        let mut ctl: Vec<Operand> = (0..CONTROL_LANES).map(|_| Em::imm(0)).collect();
130	        let tag = |em: &mut Em, v: &Operand, t: u128| em.geq(en.clone(), v.clone(), Em::imm(t));
131	        let one_of = |em: &mut Em, v: &Operand, tags: &[u128]| {
132	            let mut n = Em::imm(0);
133	            for t in tags {
134	                let h = em.teq(v.clone(), Em::imm(*t));
135	                n = em.add(n, h);
136	            }
137	            em.geq(en.clone(), n, Em::imm(1));
138	        };
139	        let regs = match rule {
140	            RuleIdC::KMachineReturnUnary => {
141	                // UnaryF { op, origin } -> PrimResult { prim result }.
142	                tag(em, &top[0], 3);
143	                one_of(em, &res[0], &[R_SCALAR_VALUE, R_EQUAL_DONE, R_SCALAR_ERROR]);
144	                let is_err = em.teq(res[0].clone(), Em::imm(R_SCALAR_ERROR));
145	                ctl[0] = Em::imm(8);
146	                ctl[1] = is_err.clone();
147	                ctl[2] = res[1].clone();
148	                ctl[3] = em.sel(is_err, Em::imm(0), res[2].clone());
149	                Regs {
150	                    origin: Some(top[2].clone()),
151	                    env: None,
152	                    pop: true,
153	                    clears_result: true,
154	                }
155	            }
156	            RuleIdC::KMachineReturnIfTrue | RuleIdC::KMachineReturnIfFalse => {
157	                // IfF { then, else, saved_env, origin } -> Eval { branch }.
158	                tag(em, &top[0], 4);
159	                let next = if rule == RuleIdC::KMachineReturnIfTrue {
160	                    top[1].clone()
161	                } else {
162	                    top[2].clone()
163	                };
164	                ctl[1] = next.clone();
165	                Regs {
166	                    origin: Some(next),
167	                    env: Some((top[3].clone(), top[4].clone())),
168	                    pop: true,
169	                    clears_result: true,
170	                }
171	            }
172	            RuleIdC::KMachineReturnMatch => {
173	                // MatchF { arms, saved_env, origin } + Return { value } ->
174	                // Cases { value, arms, saved_env }.
175	                tag(em, &top[0], 5);
176	                tag(em, &k[0], 1);
177	                ctl[0] = Em::imm(6);
178	                ctl[1] = k[1].clone();
179	                ctl[2] = k[2].clone();
180	                ctl[3..7].clone_from_slice(&top[1..5]);
181	                Regs {
182	                    origin: Some(top[5].clone()),
183	                    env: Some((top[3].clone(), top[4].clone())),
184	                    pop: true,
185	                    clears_result: false,
186	                }
187	            }
188	            RuleIdC::KMachineReturnArgumentsFinal => {
189	                // ArgsF { fname, .., saved_env, origin } + AppendDone { seq }
190	                // -> Invoke { fname, seq }.
191	                tag(em, &top[0], 6);
192	                tag(em, &res[0], R_APPEND_DONE);
193	                ctl[0] = Em::imm(3);
194	                ctl[1] = top[1].clone();
195	                ctl[2] = res[1].clone();
196	                ctl[3] = res[2].clone();
197	                Regs {
198	                    origin: Some(top[8].clone()),
199	                    env: Some((top[6].clone(), top[7].clone())),
200	                    pop: true,
201	                    clears_result: true,
202	                }
203	            }
204	            RuleIdC::KMachinePrimitiveValue => {
205	                // PrimResult { Value { value } } -> Return { value }.
206	                tag(em, &k[0], 8);
207	                tag(em, &k[1], 0);
208	                ctl[0] = Em::imm(1);
209	                ctl[1] = k[2].clone();
210	                ctl[2] = k[3].clone();
211	                Regs {
212	                    origin: None,
213	                    env: None,
214	                    pop: false,
215	                    clears_result: false,
216	                }
217	            }
218	            RuleIdC::KMachineCasesTry => {
219	                // Cases { value, arms, saved_env } + Match result ->
220	                // CaseResult { matching, value, arm(arms.start).body,
221	                // tail(arms), saved_env }.
222	                tag(em, &k[0], 6);
223	                one_of(em, &res[0], &[R_MATCH_MATCHED, R_MATCH_NO_MATCH]);
224	                let empty = em.teq(k[4].clone(), Em::imm(0));
225	                let nonempty = em.not(empty);
226	                em.gassert(en.clone(), nonempty);
227	                let arm = self
228	                    .composed
229	                    .progctx_em
230	                    .emit_prog_arm_capture(&C6ProgramContextArmCaptureInputs {
231	                        gate: en.clone(),
232	                        pre_prog: inputs.pre_prog.clone(),
233	                        caps: inputs.geometry.caps,
234	                        arm_index: k[3].clone(),
235	                    })
236	                    .map_err(|e| e.to_string())?;
237	                em.ins.extend(arm.instructions);
238	                em.gassert(en.clone(), arm.arm_found.clone());
239	                let m = em.teq(res[0].clone(), Em::imm(R_MATCH_MATCHED));
240	                // rest.len + 1 = arms.len; rest.start = len ? start + 1 : 0.
241	                let rest_start = post_i[L_CONTROL + 7].clone();
242	                let rest_len = post_i[L_CONTROL + 8].clone();
243	                let len_plus = em.add(rest_len.clone(), Em::imm(1));
244	                em.geq(en.clone(), len_plus, k[4].clone());
245	                let rest_empty = em.teq(rest_len.clone(), Em::imm(0));
246	                let start_plus = em.add(k[3].clone(), Em::imm(1));
247	                let want_start = em.sel(rest_empty, Em::imm(0), start_plus);
248	                em.geq(en.clone(), rest_start.clone(), want_start);
249	                ctl[0] = Em::imm(7);
250	                ctl[1] = m.clone();
251	                ctl[2] = em.mul(m.clone(), res[1].clone());
252	                ctl[3] = em.mul(m, res[2].clone());
253	                ctl[4] = k[1].clone();
254	                ctl[5] = k[2].clone();
255	                ctl[6] = arm.arm_row[1].clone();
256	                ctl[7] = rest_start;
257	                ctl[8] = rest_len;
258	                ctl[9] = k[5].clone();
259	                ctl[10] = k[6].clone();
260	                Regs {
261	                    origin: None,
262	                    env: None,
263	                    pop: false,
264	                    clears_result: true,
265	                }
266	            }
267	            RuleIdC::KMachineCasesMiss => {
268	                // CaseResult { .., value, rest, saved_env } -> Cases { value,
269	                // rest, saved_env }.
270	                tag(em, &k[0], 7);
271	                ctl[0] = Em::imm(6);
272	                ctl[1] = k[4].clone();
273	                ctl[2] = k[5].clone();
274	                ctl[3..7].clone_from_slice(&k[7..11]);
275	                Regs {
276	                    origin: None,
277	                    env: None,
278	                    pop: false,
279	                    clears_result: false,
280	                }
281	            }
282	            RuleIdC::KMachineCasesHit => {
283	                // CaseResult { Matched { env }, body, saved_env } ->
284	                // ScheduleNext { ScopeF { saved_env, origin }, body, env }.
285	                tag(em, &k[0], 7);
286	                tag(em, &k[1], 1);
287	                ctl[0] = Em::imm(2);
288	                ctl[1] = Em::imm(8);
289	                ctl[2] = k[9].clone();
290	                ctl[3] = k[10].clone();
291	                ctl[4] = pre_i[L_CONTROL_ORIGIN].clone();
292	                ctl[14] = k[6].clone();
293	                ctl[15] = k[2].clone();
294	                ctl[16] = k[3].clone();
295	                Regs {
296	                    origin: None,
297	                    env: None,
298	                    pop: false,
299	                    clears_result: false,
300	                }
301	            }
302	            _ => unreachable!("checked by legacy_control_supported"),
303	        };
304	        set_control(em, inputs, &ctl);
305	        let mut mutable = legacy_control_lanes();
306	        if let Some(o) = &regs.origin {
307	            em.geq(en.clone(), post_i[L_CONTROL_ORIGIN].clone(), o.clone());
308	            mutable.push(L_CONTROL_ORIGIN);
309	        }
310	        if let Some((p, i)) = &regs.env {
311	            em.geq(en.clone(), post_i[L_ENV_ROOT].clone(), p.clone());
312	            em.geq(en.clone(), post_i[L_ENV_ROOT + 1].clone(), i.clone());
313	            mutable.extend([L_ENV_ROOT, L_ENV_ROOT + 1]);
314	        }
315	        if regs.pop {
316	            pop_frame(em, inputs);
317	            mutable.push(L_FRAME_COUNT);
318	        }
319	        preserve_image(em, inputs, &mutable, regs.pop);
320	        charge_legacy(em, inputs);
321	        for (a, b) in inputs.pre_data.iter().zip(inputs.post_data.iter()) {
322	            em.geq(en.clone(), b.clone(), a.clone());
323	        }
324	        for (lane, (a, b)) in inputs
325	            .pre_helper
326	            .iter()
327	            .zip(inputs.post_helper.iter())
328	            .enumerate()
329	        {
330	            let in_result = (L_RESULT_RECORD..L_RESULT_RECORD + RESULT_LANES).contains(&lane);
331	            if regs.clears_result && in_result {
332	                em.gzero(en.clone(), b.clone());
333	            } else {
334	                em.geq(en.clone(), b.clone(), a.clone());
335	            }
336	        }
337	        compose_canonical(&mut self.composed, em, inputs)?;
338	        disabled_identity(em, inputs);
339	        Ok(())
340	    }
341	}
342	
343	/// One-shot emission of the legacy control relation for `rule`.
344	pub fn emit_c6_legacy_control_block(
345	    rule: RuleIdC,
346	    inputs: &C6StepInputs,
347	    scope: &str,
348	) -> Result<C6LegacyControlBlock, C6LegacyControlError> {
349	    C6LegacyControlEmitter::new(scope)?.emit(rule, inputs)
350	}
351

