519	/// Pre root representation checks (return_left conventions) and the full
520	/// validation of every active frame; returns the top frame lanes.
521	pub(super) fn validate_pre_image(em: &mut Em, inputs: &C6StepInputs) -> Vec<Operand> {
522	    let en = inputs.enable.clone();
523	    let caps = &inputs.geometry.caps;
524	    let p = &caps.phys;
525	    let pre_i = &inputs.pre_image;
526	    em.geq(en.clone(), pre_i[L_MAGIC].clone(), Em::imm(C6_PHYS_MAGIC));
527	    em.geq(
528	        en.clone(),
529	        pre_i[L_VERSION].clone(),
530	        Em::imm(C6_PHYS_VERSION),
531	    );
532	    em.gated_lt_index(
533	        en.clone(),
534	        pre_i[L_CONTROL_ORIGIN].clone(),
535	        p.max_expressions,
536	    );
537	    em.gated_validate_env(
538	        en.clone(),
539	        pre_i[L_ENV_ROOT].clone(),
540	        pre_i[L_ENV_ROOT + 1].clone(),
541	        p.max_env_cells,
542	    );
543	    em.gated_lt_count(en.clone(), pre_i[L_STACK_LIMIT].clone(), p.max_frames);
544	    for (at, cap) in [
545	        (L_ALLOC, p.max_data_nodes),
546	        (L_ALLOC + 1, caps.max_data_field_slots),
547	        (L_ALLOC + 2, p.max_env_cells),
548	        (L_SEG_ALLOC, p.max_data_nodes),
549	        (L_SEG_ALLOC + 1, caps.max_data_field_slots),
550	        (L_SEG_ALLOC + 2, p.max_env_cells),
551	        (L_SEG_ACTIVE, p.max_data_nodes),
552	        (L_SEG_ACTIVE + 1, caps.max_data_field_slots),
553	        (L_SEG_ACTIVE + 2, p.max_env_cells),
554	        (L_SEG_ACTIVE + 3, p.max_value_slots),
555	    ] {
556	        em.gated_lt_count(en.clone(), pre_i[at].clone(), cap);
557	    }
558	    for off in 0..4 {
559	        em.geq(
560	            en.clone(),
561	            pre_i[L_ACTIVE + off].clone(),
562	            inputs.pre_data[3 + off].clone(),
563	        );
564	    }
565	    let depth = pre_i[L_FRAME_COUNT].clone();
566	    em.gated_lt_count(en.clone(), depth.clone(), p.max_frames);
567	    let over = em.lt128(pre_i[L_STACK_LIMIT].clone(), depth.clone());
568	    let fits = em.not(over);
569	    em.gassert(en.clone(), fits);
570	    let mut top = vec![Em::imm(0); FRAME_LANES];
571	    for slot in 0..p.max_frames {
572	        let base = IMAGE_SECTION_HEADER_LANES + slot * FRAME_LANES;
573	        let active = em.lt128(Em::imm(slot as u128), depth.clone());
574	        let ga = em.and(en.clone(), active.clone());
575	        em.gated_validate_frame(ga, &pre_i[base..base + FRAME_LANES], p);
576	        let inactive = em.not(active);
577	        let gi = em.and(en.clone(), inactive);
578	        let hit = em.teq(Em::imm(slot as u128 + 1), depth.clone());
579	        for lane in 0..FRAME_LANES {
580	            em.gzero(gi.clone(), pre_i[base + lane].clone());
581	            top[lane] = em.sel(hit.clone(), pre_i[base + lane].clone(), top[lane].clone());
582	        }
583	    }
584	    top
585	}
