675	/// Retained-serial composition of META/PROG/CTX/DATA/HELPER canonicality.
676	pub(super) fn compose_canonical(
677	    composed: &mut Composed,
678	    em: &mut Em,
679	    inputs: &C6StepInputs,
680	) -> Result<(), String> {
681	    let en = inputs.enable.clone();
682	    let caps = inputs.geometry.caps;
