782	/// The header lanes an applied helper step may change.
783	pub(super) fn helper_charge_lanes() -> Vec<usize> {
784	    use mori_core::sherlock::helper_machine::c6_phys::{L_HELPER_VISITS, L_HELPER_WORK};
785	    vec![
786	        L_REMAINING_WORK,
787	        L_CONSUMED_WORK,
788	        L_HELPER_WORK,
789	        L_HELPER_VISITS,
790	    ]
791	}
