pub fn encode_control(control: &ControlC) -> [u128; CONTROL_LANES] {
    use ControlC as K;
    let mut o = [0u128; CONTROL_LANES];
    match *control {
        K::Eval { expr } => o[1] = u(expr),
        K::Return { value } => {
            o[0] = 1;
            put_ref(&mut o, 1, value);
        }
        K::ScheduleNext { frame, next, env } => {
            o[0] = 2;
            o[1..1 + FRAME_LANES].copy_from_slice(&encode_frame(&frame));
            o[14] = u(next);
            put_env(&mut o, 15, env);
        }
        K::Invoke {
            function_name,
            args,
        } => {
            o[0] = 3;
            o[1] = u(function_name);
            put_slice(&mut o, 2, args);
        }
        K::Enter { function, args } => {
            o[0] = 4;
            if let Some(function) = function {
                o[1] = 1;
                o[2] = u(function);
            }
            put_slice(&mut o, 3, args);
        }
        K::Bound {
            binding,
            return_type,
            body,
        } => {
            o[0] = 5;
            if let BoundBinding::Ok { env } = binding {
                o[1] = 1;
                put_env(&mut o, 2, env);
            }
            o[4] = u(return_type.0);
            o[5] = u(body);
        }
        K::Cases {
            value,
            arms,
            saved_env,
        } => {
            o[0] = 6;

